/* PreToken Radar — a dark trading-desk palette, one accent, consistent 8px spacing. */
:root {
  --bg: #0b0f14;
  --bg2: #11161d;
  --panel: #151c25;
  --panel2: #1a222d;
  --line: #232d3a;
  --text: #dfe7f1;
  --dim: #8fa0b5;
  --faint: #5c6b7f;
  --accent: #38d39f;
  --accent2: #4ea1ff;
  --amber: #f0b429;
  --red: #ef6461;
  --radius: 10px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text); font: 14px/1.5 "Segoe UI", system-ui, -apple-system, sans-serif; }
.skip { position: absolute; left: -9999px; }
.skip:focus { left: 8px; top: 8px; background: var(--panel); padding: 6px 10px; z-index: 10; }
a { color: var(--accent2); text-decoration: none; }

.wrap { max-width: 1240px; margin: 0 auto; padding: 0 20px 48px; }

/* Header */
header.hero { border-bottom: 1px solid var(--line); background: linear-gradient(180deg, #101720, #0b0f14); }
.hero-inner { max-width: 1240px; margin: 0 auto; padding: 26px 20px 18px; }
.brand { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.brand h1 { margin: 0; font-size: 22px; letter-spacing: 0.3px; }
.brand h1 .dot { color: var(--accent); }
.brand .ver { color: var(--faint); font-size: 12px; }
.tagline { color: var(--dim); margin: 6px 0 14px; max-width: 860px; }
.statrow { display: flex; gap: 10px; flex-wrap: wrap; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 14px; min-width: 128px; }
.stat b { display: block; font-size: 18px; color: var(--text); }
.stat span { color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.8px; }
.stat.hl b { color: var(--accent); }

/* Filter bar */
.filterbar { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; padding: 12px 0; position: sticky; top: 0; background: rgba(11,15,20,0.95); backdrop-filter: blur(4px); z-index: 5; border-bottom: 1px solid var(--line); }
.filterbar input[type="search"], .filterbar select {
  background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 8px;
  padding: 7px 10px; font: inherit; outline: none;
}
.filterbar input[type="search"] { width: 220px; }
.filterbar input[type="search"]:focus, .filterbar select:focus { border-color: var(--accent2); }
.filterbar .count { color: var(--faint); font-size: 12px; margin-left: auto; }
.chip { border: 1px solid var(--line); background: var(--panel); color: var(--dim); border-radius: 999px; padding: 5px 12px; font-size: 12px; cursor: pointer; }
.chip.on { background: rgba(56,211,159,0.14); border-color: var(--accent); color: var(--accent); }

/* Table */
table.board { width: 100%; border-collapse: collapse; margin-top: 8px; }
table.board th { text-align: left; color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.8px; padding: 8px 10px; border-bottom: 1px solid var(--line); cursor: pointer; user-select: none; white-space: nowrap; }
table.board th:hover { color: var(--dim); }
table.board th .arr { color: var(--accent); margin-left: 3px; }
table.board td { padding: 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
table.board tr.row:hover { background: var(--bg2); cursor: pointer; }
table.board tr.wl td:first-child { box-shadow: inset 3px 0 0 var(--accent); }
td.rk, td.imp, td.tvl, td.gr, td.age { white-space: nowrap; }
td.rk { color: var(--faint); font-variant-numeric: tabular-nums; }
td.imp { font-weight: 600; color: var(--accent); font-variant-numeric: tabular-nums; }
td.tvl { color: var(--dim); font-variant-numeric: tabular-nums; }
.pos { color: var(--accent); } .neg { color: var(--red); } .flat { color: var(--faint); }
.pname { font-weight: 600; }
.pname .sub { display: block; font-weight: 400; color: var(--faint); font-size: 12px; }
.badge { display: inline-block; font-size: 11px; border-radius: 6px; padding: 2px 8px; border: 1px solid var(--line); color: var(--dim); background: var(--panel2); margin-right: 4px; }
.badge.wl { border-color: var(--accent); color: var(--accent); background: rgba(56,211,159,0.1); }
.badge.mult { color: var(--amber); border-color: rgba(240,180,41,0.4); }
.chains { color: var(--faint); font-size: 12px; }

/* Detail view */
dialog.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 14px; padding: 0; width: min(720px, 92vw); max-height: 86vh; }
dialog.detail::backdrop { background: rgba(4,6,9,0.7); }
.detail .head { padding: 18px 22px 14px; border-bottom: 1px solid var(--line); display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.detail .head h2 { margin: 0; font-size: 19px; }
.detail .head .close { margin-left: auto; background: var(--panel2); border: 1px solid var(--line); color: var(--dim); border-radius: 8px; padding: 4px 12px; cursor: pointer; }
.detail .body { padding: 16px 22px 22px; overflow-y: auto; max-height: 70vh; }
.valueline { font-size: 26px; color: var(--accent); font-weight: 700; margin: 2px 0 2px; }
.valueline small { font-size: 12px; color: var(--faint); font-weight: 400; }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 14px 0; }
.kv { background: var(--bg2); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
.kv span { color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.7px; display: block; }
.kv b { font-weight: 600; }
.waterfall { margin: 12px 0; background: var(--bg2); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; }
.waterfall .step { display: flex; justify-content: space-between; padding: 3px 0; color: var(--dim); }
.waterfall .step b { color: var(--text); font-variant-numeric: tabular-nums; }
.waterfall .total { border-top: 1px solid var(--line); margin-top: 6px; padding-top: 8px; color: var(--text); }
section.plan h3, section.meth h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.8px; color: var(--faint); margin: 18px 0 8px; }
ol.steps { margin: 0; padding: 0; list-style: none; counter-reset: step; }
ol.steps li { counter-increment: step; background: var(--bg2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 14px 10px 44px; margin-bottom: 8px; position: relative; color: var(--dim); }
ol.steps li::before { content: counter(step); position: absolute; left: 12px; top: 10px; width: 22px; height: 22px; border-radius: 50%; background: rgba(56,211,159,0.15); color: var(--accent); display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; }
ol.steps li b { color: var(--text); }
.note { background: rgba(240,180,41,0.08); border: 1px solid rgba(240,180,41,0.35); color: var(--amber); border-radius: 8px; padding: 8px 12px; font-size: 12px; margin-top: 12px; }

/* Methodology */
section.meth { margin-top: 26px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 20px; }
section.meth p { color: var(--dim); margin: 6px 0; }
section.meth code { background: var(--bg2); border: 1px solid var(--line); border-radius: 4px; padding: 1px 6px; font-size: 12px; color: var(--accent2); }
table.comps { width: 100%; border-collapse: collapse; margin-top: 8px; }
table.comps td, table.comps th { padding: 6px 10px; border-bottom: 1px solid var(--line); text-align: left; font-size: 13px; }
table.comps td.n { color: var(--dim); font-variant-numeric: tabular-nums; }
footer { color: var(--faint); font-size: 12px; margin-top: 26px; }
.live-hint { color: var(--faint); font-size: 12px; margin-top: 4px; }
```

